import { describe, expect, it } from "vitest";
import { PersonId } from "@admin/world";
import { foundedForBalance } from "./balance-harness.js";
import { addDays } from "./clock.js";
import { apply } from "./effects.js";
import { issueMemberOutreach } from "./member-outreach.js";
import { resolveDueLobbying } from "./lobbying-due.js";
import { legislativeAct } from "./legislative-acts.js";
import { legislationPhase } from "./legislation.js";
import { projectPassage } from "./bill-stages.js";
import { carried } from "./congress.js";
import { issuePreference, knownPersonContacts } from "./person-network-influence.js";
import { outreachAttentionSpent } from "./lobbying-person.js";
const founded = foundedForBalance("observed-issue-coalition").campaign;
const bill = { id: "bill:outreach-budget", act: "act-equal-protection", title: "Equal Protection Enforcement Act", status: "in-progress", sponsor: "administration", introducedTurn: 0, stage: "floor", momentum: 0.17, passage: [] };
// These actual senators were observed just short of cloture on this seeded bill.
const targets = [2086, 2104, 2205].map((index) => PersonId.parse(`PER-USA-congressional-leader-${index}`));
const source = PersonId.parse("PER-USA-attorney-general-10");
function request(campaign, target, broker) {
    const issued = issueMemberOutreach(campaign, target, bill.id, broker);
    if (!issued.ok)
        throw new Error(issued.reason);
    return apply(campaign, issued.packet);
}
function resolve(campaign, days) {
    return resolveDueLobbying({ ...campaign, calendar: addDays(campaign.calendar, days) }).campaign;
}
function baseline() {
    let campaign = { ...founded, bills: { ...founded.bills, [bill.id]: bill } };
    for (const target of targets) {
        // Contact history is generated by actual authorized/answered outreach.
        campaign = resolve(request(campaign, target, source), 3);
        campaign = { ...campaign, calendar: addDays(campaign.calendar, 1) };
    }
    // The new sitting follows the four elapsed weeks of contact building and expiry.
    const expired = { ...campaign, turn: 5, calendar: addDays(campaign.calendar, 22) };
    const openingCount = projectPassage(expired, legislativeAct(bill.act), bill.momentum, bill.id);
    return { ...expired, bills: { ...expired.bills, [bill.id]: { ...bill, passage: openingCount } } };
}
const ready = baseline();
describe("equal presidential attention on an actual legislative roster", () => {
    it("compares two direct calls with one brokerage effort through real prior contacts", () => {
        expect(ready.congress.members).toHaveLength(535);
        expect(carried(ready.bills[bill.id].passage)).toBe(false);
        for (const target of targets) {
            expect(ready.congress.members.some((member) => member.person === target && member.chamber === "senate")).toBe(true);
            expect(issuePreference(ready, target, bill)).toBeGreaterThan(0);
            expect(knownPersonContacts(ready, bill.act).some((edge) => edge.from === source && edge.to === target)).toBe(true);
        }
        const directPending = request(request(ready, targets[0]), targets[1]);
        const brokerPending = request(ready, targets[0], source);
        expect(outreachAttentionSpent(directPending)).toBe(2);
        expect(outreachAttentionSpent(brokerPending)).toBe(2);
        expect(directPending.player.metrics.standing).toBeCloseTo(brokerPending.player.metrics.standing, 12);
        const direct = resolve(directPending, 3), broker = resolve(brokerPending, 3);
        const act = legislativeAct(bill.act);
        const directVotes = projectPassage(direct, act, bill.momentum, bill.id);
        const brokerVotes = projectPassage(broker, act, bill.momentum, bill.id);
        expect(directVotes[1]?.cloture?.yeas).toBe(59);
        expect(brokerVotes[1]?.cloture?.yeas).toBe(60);
        expect(carried(directVotes)).toBe(false);
        expect(carried(brokerVotes)).toBe(true);
        expect(directVotes[1]?.rollCall).toHaveLength(100);
        expect(brokerVotes[1]?.rollCall).toHaveLength(100);
        const directFloor = legislationPhase(direct).reduce(apply, direct);
        const brokerFloor = legislationPhase(broker).reduce(apply, broker);
        expect(directFloor.bills[bill.id]?.status).toBe("dead");
        expect(brokerFloor.bills[bill.id]?.status).toBe("on-the-desk");
    });
    it("an independently principled contact can refuse the same broker and prevent passage", () => {
        const target = targets[2];
        const runtime = ready.people[target];
        const opposing = { ...ready, people: { ...ready.people, [target]: { ...runtime, base: { ...runtime.base, integrity: 1, ideology: { economicLeftRight: -1, authLibertarian: 1, nationalistGlobalist: 1 } } } } };
        const answered = resolve(request(opposing, targets[0], source), 3);
        const response = answered.congress.lobbying.at(-1)?.cooperation?.find((edge) => edge.to === target);
        expect(response?.accepted).toBe(false);
        const votes = projectPassage(answered, legislativeAct(bill.act), bill.momentum, bill.id);
        expect(carried(votes)).toBe(false);
        expect(votes[1]?.cloture?.yeas).toBeLessThan(60);
    });
});
